import {writeFileSync} from 'node:fs';

// Handwritten synthetic scenario. The page and selected block identifiers are
// stable regression coordinates, not references to an actual procurement file.
const id='roof-v2',fileName='示例办公楼屋面改造-合成测试.pdf';
const blocks=[];
const add=(number,page,section,text,extra={})=>{
  const block={id:`${id}:b${number}`,documentId:id,fileName,text,normalizedText:text.normalize('NFKC'),page,section,kind:'paragraph',heading:null,...extra};
  blocks.push(block);return block;
};
const table=(number,page,section,headers,rows,extra={})=>{
  const tableRows=rows.map(cells=>({cells,text:cells.join(' | '),page,headers}));
  return add(number,page,section,[headers.join(' | '),...tableRows.map(row=>row.text)].join('\n'),{kind:'table',tableRows,tableHeaders:headers,tableId:`synthetic-table-${number}`,...extra});
};

